export function diff(dom, parentDom, newVNode, oldVNode, context, isSvg, excessDomChildren, mounts, ancestorComponent, force) {
	let c, p, isNew = false, oldProps, oldState, snapshot,
		newType = newVNode.type;

	try {
		outer: if (typeof newType==='function') {
			let cxType = newType.contextType;
			let isProvider = newType._id==='Provider';

			if (oldVNode._component) {
				c = newVNode._component = oldVNode._component;
			}
			else {
				if (newType.prototype && newType.prototype.render) {
					newVNode._component = c = new newType(newVNode.props, context);
				}
				else {
					newVNode._component = c = new Component(newVNode.props, context);
					c.constructor = newType;
					c.render = doRender;
				}
			}

			c.props = newVNode.props;

			if (!force && c.shouldComponentUpdate!=null &&
				c.shouldComponentUpdate(newVNode.props, c._nextState || c.state, context)===false) {
				c.props = newVNode.props;
				break outer;
			}

			if (newType._id==='_P' && c.props.value!==newVNode.props.value) {
				const v = newVNode.props.value;
				newVNode._component.subs.map(sub => v!==sub.context && (sub.context = v, enqueueRender(sub)));
			}
		}
	}
	catch (e) {
		catchErrorInComponent(e, ancestorComponent);
	}
}
</context>


