+// tlfKey generates a TLF cache key from a tlf.ID and a binary-encoded block
+// ID.
+func (*DiskBlockCacheStandard) tlfKey(tlfID tlf.ID, blockKey []byte) []byte {
+	return append(tlfID.Bytes(), blockKey...)
