+// Size implements the DiskBlockCache interface for DiskBlockCacheStandard.
+func (cache *DiskBlockCacheStandard) Size() int64 {
+	cache.lock.RLock()
+	defer cache.lock.RUnlock()
+	return int64(cache.currBytes)
