		if err := metricsReporter.ReportLatency(*ctx, time.Now().Sub(*latestUpdateTime), resourceKind, resourceName); err != nil {
			logging.FromContext(*ctx).Error("Failed to report latency", zap.Error(err))
		}
	}
}
