private void Output(LogEventInfo logEvent, string message)
{
    ConsoleColor oldForegroundColor = Console.ForegroundColor;
    ConsoleColor oldBackgroundColor = Console.BackgroundColor;

    try
    {
        var matchingRule = FindConsoleRowHighlightingRule(logEvent);
        SetUpConsoleColors(matchingRule);

        message = message.Replace("\a", "\a\a");

        for (int index = 0; index < this.WordHighlightingRules.Count; index++)
        {
            ConsoleWordHighlightingRule hl = this.WordHighlightingRules[index];
            message = hl.ReplaceWithEscapeSequences(message);
        }

        ColorizeEscapeSequences(
            this.ErrorStream ? Console.Error : Console.Out,
            message,
            new ColorPair(Console.ForegroundColor, Console.BackgroundColor),
            new ColorPair(oldForegroundColor, oldBackgroundColor));
    }
    finally
    {
        Console.ForegroundColor = oldForegroundColor;
        Console.BackgroundColor = oldBackgroundColor;
    }

    if (this.ErrorStream)
    {
        Console.Error.WriteLine();
    }
    else
    {
        Console.WriteLine();
    }
}
</context>


