<context>
void ColladaParser::CopyVertex(size_t currentVertex, size_t numOffsets, size_t numPoints,
	size_t perVertexOffset, Mesh* pMesh, std::vector<InputChannel>& pPerIndexChannels,
	size_t currentPrimitive, const std::vector<size_t>& indices)
{
	size_t maxIndexRequested = currentPrimitive * numOffsets * numPoints +
		(currentVertex + 1) * numOffsets - 1;
	ai_assert(maxIndexRequested < indices.size());

	std::vector<size_t> vindex;
	vindex.reserve(numOffsets);

	for (size_t offsets = 0; offsets < numOffsets; ++offsets)
		vindex[offsets] = indices[currentPrimitive * numOffsets * numPoints +
			currentVertex * numOffsets + offsets];

	for (std::vector<InputChannel>::iterator it = pMesh->mPerVertexData.begin();
		it != pMesh->mPerVertexData.end(); ++it)
		ExtractDataObjectFromChannel(*it, vindex[perVertexOffset], pMesh);

	for (std::vector<InputChannel>::iterator it = pPerIndexChannels.begin();
		it != pPerIndexChannels.end(); ++it)
		ExtractDataObjectFromChannel(*it, vindex[it->mOffset], pMesh);

	pMesh->mFacePosIndices.push_back(vindex[perVertexOffset]);
}

void ColladaParser::ExtractDataObjectFromChannel(const InputChannel& pInput,
	size_t pLocalIndex, Mesh* pMesh)
{
	if (pInput.mType == IT_Vertex)
		return;

	const Accessor& acc = *pInput.mResolved;
	if (pLocalIndex >= acc.mCount)
		ThrowException("Invalid data index in primitive specification");
}
