                            ClientSecrets = { new Secret(applicationConfiguration.Id.Sha256()) },
                            AllowedScopes = { DevelopmentIdentityProviderConfiguration.Audience },
                            Claims = applicationConfiguration.Roles
                                .Select(r => new Claim("roles", r))
                                .Concat(new[] { new Claim("appid", applicationConfiguration.Id) })
                                .ToList(),
                            ClientClaimsPrefix = string.Empty,
                        }));
    }

    return services;
}
